CREATE INDEX IF NOT EXISTS idx_curated_apps_record_hash    ON curated_apps (record_hash);
CREATE INDEX IF NOT EXISTS idx_curated_apps_conflict       ON curated_apps (flag_conflicting_label);

-- Pipeline run audit trail.
CREATE TABLE IF NOT EXISTS pipeline_runs (
    run_id            TEXT PRIMARY KEY,
    stage             TEXT NOT NULL,
    started_at_utc    TIMESTAMPTZ NOT NULL DEFAULT now(),
    finished_at_utc   TIMESTAMPTZ,
    status            TEXT NOT NULL DEFAULT 'running',
    rows_in           BIGINT,
    rows_out          BIGINT,
    notes             TEXT
);

-- Metric snapshots per evaluation run.
CREATE TABLE IF NOT EXISTS model_metrics (
    evaluate_run_id   TEXT NOT NULL,
    model             TEXT NOT NULL,
    metric            TEXT NOT NULL,
    value             DOUBLE PRECISION NOT NULL,
    loaded_at_utc     TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (evaluate_run_id, model, metric)
);

-- Partial partition example: rows flagged as conflicting labels.
CREATE TABLE IF NOT EXISTS curated_apps_conflicting (
    LIKE curated_apps INCLUDING ALL
);

